import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {applyLocales,assertScreeningCopy,assertScreeningRows,SCREENING_BASE,SCREENING_LANGS,FLOW_LANGS,SCREENING_KEYS,USER_CUSTOM_KEYS} from './apply-screening.mjs';
const baselineBytes=readFileSync(new URL('./fixtures/apply-screening-f89.json',import.meta.url));
assert.equal(createHash('sha256').update(baselineBytes).digest('hex'),'0122fdf6697044666c4d424b78af61525996da5bf2932b92176d3d866be1beee','Immutable extracted old source fixture');
const baseline=JSON.parse(baselineBytes);assert.equal(baseline.ref,SCREENING_BASE);
test('actual pinned base exposes the sixteen English screening fallbacks',()=>{const l=baseline.i18n;for(const lang of SCREENING_LANGS)assert.equal(l.locales[lang].step3Title,l.locales.en.step3Title);assert.throws(()=>assertScreeningCopy(l));});
test('screening copy covers all sixteen languages and20 footer notices; unchanged locale/operating data',()=>{const now=applyLocales(),old=baseline.i18n;assertScreeningCopy(now);assert.deepEqual(now.languages,old.languages);assert.deepEqual(now.internal,old.internal);for(const lang of ['pl','ru','uk','en']){const {footerNotice,footerPrivacyLabel,...rest}=now.locales[lang];assert.deepEqual(rest,old.locales[lang]);}for(const lang of SCREENING_LANGS)for(const key of SCREENING_KEYS){const broken=structuredClone(now);broken.locales[lang][key]=now.locales.en[key];assert.throws(()=>assertScreeningCopy(broken));}});
const valid=()=>[320,1280].flatMap(width=>FLOW_LANGS.map(lang=>({width,lang,status:'passed',steps:true,labels:true,options:true,conditional:true,answers:true,review:true,back:true,resumed:true,fits:true,painted:true,iconsOneLine:true,progressOneLine:true,direction:true,phoneLTR:true,noDelivery:true})));
test('screening browser gate requires40 unique complete visible flows',()=>{assert.doesNotThrow(()=>assertScreeningRows(valid()));for(const rows of [valid().slice(1),valid().map((r,i,a)=>i===1?a[0]:r)])assert.throws(()=>assertScreeningRows(rows));for(const key of ['steps','labels','options','conditional','answers','review','back','resumed','fits','painted','iconsOneLine','progressOneLine','direction','phoneLTR','noDelivery']){const rows=valid();rows[0][key]=false;assert.throws(()=>assertScreeningRows(rows));}});

test('Localized screening locales have complete user-facing review/recovery copy and an explicit sixteen-language matrix',()=>{assert.deepEqual(SCREENING_LANGS,['ka','az','hy','tr','uz','id','fil','vi','hi','ne','ky','tg','kk','bn','ur','si']);assert.deepEqual(FLOW_LANGS,['pl','uk','ru','en',...SCREENING_LANGS]);const now=applyLocales();for(const lang of SCREENING_LANGS)for(const key of [...USER_CUSTOM_KEYS,...(['ky','tg','kk','bn','ur','si'].includes(lang)?['phoneHint','locationHint']:[])]){const broken=structuredClone(now);broken.locales[lang][key]=now.locales.en[key];assert.throws(()=>assertScreeningCopy(broken),assert.AssertionError,lang+':'+key);}});
